    lines = []
    lines.append(title_border(W2, 'Veritas NetBackup'))
    lines.append(txt_row())
    lines.append(R(bTop(IV_L, IV_R)))
    lines.append(R(bMid(IV_L, IV_R, 'Enterprise backup — Master/Media servers, policies, NetBackup catalog')))
    lines.append(R(bMid(IV_L, IV_R, 'Protocols: NDMP · VTL emulation · DD Boost · TCP 1556 (PBX/vnetd)')))
    lines.append(R(bMid(IV_L, IV_R, 'Management: NetBackup Admin Console / OpsCenter / Web UI (10.x)')))
    lines.append(R(bMid(IV_L, IV_R, 'Policy schedule -> Master server -> Media server -> Storage unit -> Client')))
    lines.append(R(bBot(IV_L, IV_R)))
    lines.append(txt_row())
    lines.append(R(arrow([M1, M2, M3])))
    lines.append(txt_row())
    lines.append(R(merge(bTop(B1_L, B1_R), bTop(B2_L, B2_R), bTop(B3_L, B3_R))))
    lines.append(R(merge(bMid(B1_L, B1_R, 'Layer'), bMid(B2_L, B2_R, 'Component'), bMid(B3_L, B3_R, 'Notes'))))
    lines.append(R(merge(bMid(B1_L, B1_R, 'Control'), bMid(B2_L, B2_R, 'Master server'), bMid(B3_L, B3_R, 'Catalog (NBDB), policies'))))
    lines.append(R(merge(bMid(B1_L, B1_R, 'Data mover'), bMid(B2_L, B2_R, 'Media server'), bMid(B3_L, B3_R, 'Writes to storage units'))))
    lines.append(R(merge(bMid(B1_L, B1_R, 'Client'), bMid(B2_L, B2_R, 'bpcd agent'), bMid(B3_L, B3_R, 'Per-host backup agent'))))
    lines.append(R(merge(bMid(B1_L, B1_R, 'Storage'), bMid(B2_L, B2_R, 'Storage unit / DD'), bMid(B3_L, B3_R, 'Disk, tape, DD Boost'))))
    lines.append(R(merge(bMid(B1_L, B1_R, 'Certs'), bMid(B2_L, B2_R, 'Host ID certificates'), bMid(B3_L, B3_R, 'NBU 8.x+ mandatory'))))
    lines.append(R(merge(bBot(B1_L, B1_R), bBot(B2_L, B2_R), bBot(B3_L, B3_R))))
    lines.append(txt_row())
    lines.append(R(arrow([M1, M2, M3])))
    lines.append(txt_row())
    lines.append(R(bTop(IV_L, IV_R)))
    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['Component', 'Purpose', 'Protocol', 'Auth', 'Notes'])))
    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['Master server', 'Catalog+schedule', 'TCP 1556', 'Cert (NBU 8+)', 'NBDB Sybase-based'])))
    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['Media server', 'Data movement', 'TCP 1556', 'Cert', 'Many per master'])))
    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['bpcd', 'Client agent', 'TCP 1556', 'Cert', 'Each client runs'])))
    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['AIR', 'Auto Img Replic.', 'TCP 1556', 'Cert', 'Cross-domain copy'])))
    lines.append(R(bBot(IV_L, IV_R)))
    lines.append(txt_row())
    lines.append(txt_row('Physical: master server - media servers - Data Domain/tape library - clients'))
    lines.append(txt_row())
    lines.append(txt_row('Key terms:'))
    lines.append(txt_row())
    lines.append(txt_row('Master server  = central control plane; owns the catalog and policies'))
    lines.append(txt_row('Media server   = writes backup data to storage units; can combine with master'))
    lines.append(txt_row('NBDB           = NetBackup relational database (Sybase) storing the catalog'))
    lines.append(txt_row('Policy         = defines schedule, client list, and backup type for clients'))
    lines.append(txt_row('Storage unit   = logical target (disk pool, tape, cloud) media servers write to'))
    lines.append(txt_row('bpcd           = NetBackup client daemon listening for backup/restore requests'))
    lines.append(txt_row('vnetd          = NetBackup network daemon; multiplexes traffic over fewer ports'))
    lines.append(txt_row('AIR            = Auto Image Replication; replicates images between NBU domains'))
    lines.append(txt_row('Host ID cert   = NBU 8.x+ mandatory cert authenticating client to master'))
    lines.append(txt_row('DD Boost       = NetBackup-to-Data-Domain dedup offload integration'))
    lines.append(txt_row('Catalog backup = backup of the NBDB itself; critical for full env recovery'))
    lines.append(txt_row('bpps           = command listing active NetBackup processes for triage'))
    lines.append(txt_row())
    lines.append('└' + '─' * W2 + '┘')
    return lines


