    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['pg_dump', 'Logical backup', 'N/A', 'DB user', 'Per-DB export'])))
    lines.append(R(bBot(IV_L, IV_R)))
