    lines.append(txt_row('MVCC           = Multi-Version Concurrency Control; readers never block writers'))
    lines.append(txt_row('WAL            = Write-Ahead Log; basis for replication and crash recovery'))
    lines.append(txt_row('Autovacuum     = background process reclaiming space from dead rows'))
    lines.append(txt_row('TXID wraparound= critical failure if vacuum falls badly behind'))
    lines.append(txt_row('Patroni        = open-source HA template managing automatic failover'))
    lines.append(txt_row('pg_stat_activity = view of current connections and running queries'))
    lines.append(txt_row('Replication slot = reserves WAL on primary so replica retains segments'))
    lines.append(txt_row('pg_hba.conf    = host-based auth rules controlling who can connect'))
    lines.append(txt_row('Logical repl.  = row-level replication, can target a subset of tables'))
    lines.append(txt_row('Checkpoint     = periodic dirty-buffer flush, reduces crash recovery time'))
    lines.append(txt_row('VACUUM FREEZE  = aggressive vacuum preventing transaction ID wraparound'))
    lines.append(txt_row('HAProxy check  = routes traffic only to the current Patroni primary'))
    lines.append(txt_row())
    lines.append('└' + '─' * W2 + '┘')
    return lines


