    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['showmount', 'Lists exports', 'TCP/UDP 2049', 'N/A', 'showmount -e'])))
    lines.append(R(bBot(IV_L, IV_R)))
    lines.append(txt_row())
    lines.append(txt_row('Physical: NFS server (array or Linux host) - client hosts - IP network'))
    lines.append(txt_row())
    lines.append(txt_row('Key terms:'))
    lines.append(txt_row())
    lines.append(txt_row('Export         = a server-side directory made available to clients'))
    lines.append(txt_row('NFSv3          = stateless; needs portmapper + mountd alongside nfsd'))
    lines.append(txt_row('NFSv4.1        = stateful; only port 2049, built-in locking'))
    lines.append(txt_row('root_squash    = maps remote root to a non-privileged server user'))
    lines.append(txt_row('no_root_squash = disables root squashing; security risk if misused'))
    lines.append(txt_row('Stale handle   = client cached handle no longer matches server state'))
    lines.append(txt_row('idmapd         = maps NFSv4 numeric IDs to/from names via a domain'))
    lines.append(txt_row('NFS domain     = string client and server idmapd must agree on'))
    lines.append(txt_row('async export   = server acks writes before disk; faster, riskier'))
    lines.append(txt_row('NLM            = Network Lock Manager; file locking for NFSv3'))
    lines.append(txt_row('Hard vs soft   = hard retries forever, soft can return I/O errors'))
    lines.append(txt_row('showmount      = client tool listing the exported paths on a server'))
    lines.append(txt_row())
    lines.append('└' + '─' * W2 + '┘')
    return lines


