    lines.append(txt_row('Handshake      = negotiation establishing a session before data flows'))
    lines.append(txt_row('Cipher suite   = combination of algorithms used for a TLS session'))
    lines.append(txt_row('SAN            = Subject Alternative Name; modern hostname match field'))
    lines.append(txt_row('CN             = Common Name; legacy field, ignored by modern browsers'))
    lines.append(txt_row('Root CA        = top-level trusted CA anchoring a chain'))
    lines.append(txt_row('Intermediate CA= bridges a root CA to issued leaf certs'))
    lines.append(txt_row('mTLS           = mutual TLS; both sides present certificates'))
    lines.append(txt_row('ALPN           = Application-Layer Protocol Negotiation (HTTP/2)'))
    lines.append(txt_row('SNI            = Server Name Indication; hostname sent before cert'))
    lines.append(txt_row('Forward secrecy= session keys safe even if long-term key leaks'))
    lines.append(txt_row('TLS termination= decrypting at a proxy/LB before forwarding plaintext'))
    lines.append(txt_row('OCSP stapling  = server includes revocation status in the handshake'))
    lines.append(txt_row())
    lines.append('└' + '─' * W2 + '┘')
    return lines


