    lines.append(txt_row('Policy folder = Venafi object defining CA, key length, SAN, and renewal rules'))
    lines.append(txt_row('CA connector = plugin linking Venafi to a specific certificate authority'))
    lines.append(txt_row('VCert        = Venafi CLI tool for enroll/renew from pipelines and automation'))
    lines.append(txt_row('Discovery    = Venafi network scanner finding TLS certs on reachable hosts/ports'))
    lines.append(txt_row('Adaptable CA = custom Venafi driver for CAs without a built-in connector'))
    lines.append(txt_row('ACME         = RFC 8555 protocol supported by Venafi for automated cert issuance'))
    lines.append(txt_row('EST          = Enrollment over Secure Transport; RFC 7030 device enrolment'))
    lines.append(txt_row('Machine ID   = Venafi term for any TLS/SSH key managed by the platform'))
    lines.append(txt_row('Expiry alert = Venafi notification sent before a certificate expires (configurable)'))
    lines.append(txt_row('Terraform    = Venafi Terraform provider for IaC-driven cert lifecycle'))
    lines.append(txt_row())
    lines.append('└' + '─' * W2 + '┘')
    return lines


