    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['Splitter', 'Write intercept', 'FC / iSCSI', 'N/A', 'On array or fabric'])))
    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['Journal', 'Write log', 'Internal', 'N/A', 'Sized for RPO'])))
    lines.append(R(sections(IV_L, IV_R, [PD1, PD2, PD3, PD4], ['RPMA', 'Management UI', 'HTTPS 443', 'Admin account', 'Java web app'])))
    lines.append(R(bBot(IV_L, IV_R)))
