    lines.append(txt_row())
    lines.append(txt_row('RPA          = RecoverPoint Appliance; physical or virtual appliance per site'))
    lines.append(txt_row('CG           = Consistency Group; set of volumes protected and recovered together'))
    lines.append(txt_row('Journal      = RecoverPoint write log; stores all changes to enable any-point recovery'))
    lines.append(txt_row('Splitter     = intercepts host writes; sends copy to RPA journal simultaneously'))
    lines.append(txt_row('RPO          = Recovery Point Objective; max data loss; linked to replication lag'))
    lines.append(txt_row('APIT         = Any Point In Time; RecoverPoint capability to restore to any second'))
    lines.append(txt_row('Bookmark     = user-labeled APIT recovery point; e.g. before a patch'))
    lines.append(txt_row('Image access = mount a past journal image to a host without failing over'))
    lines.append(txt_row('Failover     = activate the replica copy at DR site; reverse replication to recover'))
    lines.append(txt_row('WAN          = IP link between RPA clusters; RecoverPoint replicates journal over WAN'))
    lines.append(txt_row('RPMA         = RecoverPoint Management Application; Java-based management UI'))
    lines.append(txt_row('Lag          = difference in write log between production and replica; drives RPO'))
    lines.append(txt_row())
    lines.append('└' + '─' * W2 + '┘')
    return lines


