    lines.append(txt_row('Cycle time   = interval at which delta sets are committed and transferred'))
    lines.append(txt_row('RA port      = SRDF port on PowerMax; dedicated to replication link traffic'))
    lines.append(txt_row('RDFA         = Remote Data Facility Async; older term for SRDF/A'))
    lines.append(txt_row('SRDF group   = logical link between R1 and R2; defines RA ports used'))
    lines.append(txt_row('Consistency  = all R2 volumes in a group updated together per cycle'))
    lines.append(txt_row('Suspend      = pauses replication; delta set accumulates until resumed'))
    lines.append(txt_row('SMC          = Solutions Management Console; Java SRDF management GUI'))
    lines.append(txt_row())
    lines.append('└' + '─' * W2 + '┘')
    return lines


