    lines.append(txt_row('DFW          = Distributed Firewall; stateful per-vNIC firewall in ESXi kernel'))
    lines.append(txt_row('Transport node = ESXi host or Edge VM with NSX data plane kernel modules'))
    lines.append(txt_row('TEP          = Tunnel End Point; IP on transport node for GENEVE encapsulation'))
    lines.append(txt_row('GENEVE       = Generic Network Virtualization Encapsulation; NSX overlay protocol'))
    lines.append(txt_row('Segment      = NSX logical switch (L2 domain) running over GENEVE overlay'))
    lines.append(txt_row('Tier-0 GW    = NSX North/South gateway; runs BGP to physical upstream'))
    lines.append(txt_row('Tier-1 GW    = NSX East/West gateway; tenant-level routing'))
    lines.append(txt_row('Edge cluster = group of Edge nodes providing N/S routing and gateway services'))
    lines.append(txt_row('BFD          = Bidirectional Forwarding Detection; sub-second link failure detection'))
    lines.append(txt_row('BGP          = Border Gateway Protocol; Tier-0 routing to physical network'))
    lines.append(txt_row('Policy API   = preferred NSX REST API; declarative intent-based config'))
    lines.append(txt_row('Manager API  = legacy NSX API; still works but Policy API preferred for new config'))
    lines.append(txt_row())
    lines.append('└' + '─' * W2 + '┘')
    return lines
